function validate([salary]) {
  if (salary.length < 3 || salary.length > 100) return 'salary needs 3 to 100 values.';
  if (salary.some(v => v < 1000 || v > 1000000)) return 'Each salary is between 1000 and 10^6.';
  if (new Set(salary).size !== salary.length) return 'Salaries must all be different.';
  return null;
}

