function average(salary) {
  let total = 0;
  let low = Infinity;
  let high = -Infinity;
  for (const pay of salary) {
    total += pay;
    low = Math.min(low, pay);
    high = Math.max(high, pay);
  }
  return (total - low - high) / (salary.length - 2);
}

