function generate(rand, size) {
  const n = size === 'large' ? 100 : 3 + Math.floor(rand() * 6);
  const span = size === 'large' || rand() < 0.5 ? 999000 : 20;
  const seen = new Set();
  while (seen.size < n) seen.add(1000 + Math.floor(rand() * (span + 1)));
  return [[...seen]];
}
